demo_api.py:
"""Нумерологічні ендпоінти для статичної демо-версії (виконується в Pyodide).

Логіка дзеркалить devserver.py; сама математика й тексти — справжній пакет
numerology/, без змін."""
import datetime as _dt
import json

import numerology
from numerology import content as nc


def _bad_birthdate(raw, prefix=""):
    raw = (raw or "").strip()
    if not raw:
        return {"ok": False, "code": prefix + "birthdate_required", "error": "Вкажи дату народження"}
    try:
        bd = _dt.datetime.strptime(raw, "%d.%m.%Y")
    except ValueError:
        return {"ok": False, "code": prefix + "birthdate_format",
                "error": "Невірний формат дати. Введи у форматі ДД.ММ.РРРР"}
    now = _dt.datetime.now()
    if bd.date() >= now.date():
        return {"ok": False, "code": prefix + "birthdate_future",
                "error": "Дата народження не може бути сьогоднішньою або майбутньою"}
    if (now - bd).days > 150 * 365:
        return {"ok": False, "code": prefix + "birthdate_too_old",
                "error": "Дата народження не може бути давнішою за 150 років"}
    return None


def _titles():
    return {str(k): v for k, v in nc.energy_titles().items()}


def handle(method, path, query_json, body_json, profile_birthdate):
    qs = json.loads(query_json or "{}")
    body = json.loads(body_json or "{}")
    status, out = _route(method, path, qs, body, profile_birthdate or "")
    return json.dumps([status, out], ensure_ascii=False)


def _route(method, path, qs, body, profile_bd):
    if path == "/api/numerology/energy":
        if qs.get("context") == "karmic_tail":
            tail = nc.karmic_tail(qs.get("code", ""))
            if tail is None:
                return 404, {"ok": False, "code": "numerology_energy_range",
                             "error": "Немає опису для цього кармічного коду"}
            return 200, {"ok": True, "karmicTail": tail}
        energy = nc.energy(qs.get("n"))
        if energy is None:
            return 400, {"ok": False, "code": "numerology_energy_range",
                         "error": "Енергія має бути числом від 1 до 22"}
        return 200, {"ok": True, "energy": energy}

    if path == "/api/numerology/block":
        block_id = (qs.get("id") or "").strip()
        nums = [x.strip() for x in (qs.get("n") or "").split(",") if x.strip()][:16]
        items = nc.block_texts(block_id, nums) if block_id else []
        if not items:
            return 400, {"ok": False, "code": "numerology_energy_range",
                         "error": "Енергія має бути числом від 1 до 22"}
        return 200, {"ok": True, "block": block_id, "items": items,
                     "disclaimer": nc.block_disclaimer(block_id),
                     "contentLang": nc.SOURCE_LANG}

    if path in ("/api/numerology/matrix", "/api/numerology/compatibility"):
        raw = (body.get("birthdate") or profile_bd or "").strip()
        bad = _bad_birthdate(raw)
        if bad:
            return 400, bad
        if path.endswith("/matrix"):
            matrix = numerology.matrix_from_date(raw)
            return 200, {"ok": True, "birthdate": raw, "matrix": matrix,
                         "hints": nc.all_hints(), "energyTitles": _titles(),
                         "karmicTail": nc.karmic_tail(matrix["karmicTail"]),
                         "contentLang": nc.SOURCE_LANG}
        partner = (body.get("partner_birthdate") or "").strip()
        bad = _bad_birthdate(partner, prefix="partner_")
        if bad:
            return 400, bad
        pair = numerology.compatibility_matrix(numerology.matrix_from_date(raw),
                                               numerology.matrix_from_date(partner))
        return 200, {"ok": True, "birthdate": raw, "partnerBirthdate": partner, "pair": pair,
                     "hints": nc.all_hints(), "energyTitles": _titles(),
                     "karmicTail": nc.karmic_tail(pair["karmicTail"]),
                     "contentLang": nc.SOURCE_LANG}
    return 404, {"ok": False, "error": "not found"}
